  do48: ['Que futebolista português ganhou cinco Bolas de Ouro?', ['Cristiano Ronaldo', 'Luís Figo', 'Eusébio', 'Rui Costa'], 'Cristiano Ronaldo ganhou a Bola de Ouro em 2008, 2013, 2014, 2016 e 2017.'],
  do49: ['Em que cidade se realizaram os Jogos Olímpicos de 2016?', ['Londres', 'Rio de Janeiro', 'Pequim', 'Tóquio'], 'Foram os primeiros Jogos Olímpicos realizados na América do Sul.'],
  do50: ['Quantos jogadores tem uma equipa de polo aquático na água?', ['Cinco', 'Seis', 'Sete', 'Oito'], 'Seis jogadores de campo e um guarda-redes.'],
  do51: ['Como se chama a grande corrida de ciclismo por etapas que se disputa todos os anos em Espanha?', ['O Tour', 'O Giro', 'O Paris-Roubaix', 'A Vuelta'], 'A Volta a Espanha é uma das três grandes voltas, com o Tour de França e o Giro de Itália.'],
  do52: ['Que tenista espanhola ganhou Wimbledon em 2017?', ['Garbiñe Muguruza', 'Arantxa Sánchez Vicario', 'Conchita Martínez', 'Carla Suárez'], 'Garbiñe Muguruza venceu Venus Williams na final.'],
  do53: ['Que videojogo de construção com blocos criou Markus Persson?', ['Fortnite', 'Minecraft', 'Tetris', 'Roblox'], 'O Minecraft foi lançado oficialmente em 2011.'],
  do54: ['Que jogo de lógica japonês consiste em preencher uma grelha de 9 × 9 com números de 1 a 9?', ['Kakuro', 'Origami', 'Sudoku', 'Tangram'], 'Nenhum número se pode repetir na mesma linha, coluna ou quadrado de 3 × 3.'],
  do55: ['Que atleta jamaicano tem o recorde mundial dos 100 metros?', ['Yohan Blake', 'Asafa Powell', 'Carl Lewis', 'Usain Bolt'], 'Usain Bolt correu em 9,58 segundos em Berlim, em 2009.'],
  do56: ['Que desporto de raquete se joga a pares num campo fechado com paredes de vidro?', ['Padel', 'Squash', 'Badminton', 'Frontenis'], 'O padel nasceu no México em 1969 e hoje é muito popular em Espanha e Portugal.'],
  do57: ['Quantos pontos são precisos para ganhar um set no voleibol (exceto o quinto)?', ['15', '21', '25', '30'], 'Ganha-se com 25 pontos e pelo menos dois de vantagem; o quinto set joga-se até 15.'],
  do58: ['Que clube português ganhou a Taça dos Campeões Europeus em 1961 e 1962?', ['Sporting', 'FC Porto', 'Benfica', 'Braga'], 'O Benfica de Eusébio ganhou duas Taças dos Campeões seguidas.'],
  do59: ['Que distância total se nada, pedala e corre num triatlo olímpico?', ['51,5 km', '42,2 km', '100 km', '226 km'], '1,5 km a nadar, 40 km de bicicleta e 10 km a correr.'],
  do60: ['Que jogo de tabuleiro usa um tabuleiro de 15 × 15 casas e peças com letras?', ['Scrabble', 'Cluedo', 'Risco', 'Pictionary'], 'Cada letra tem um valor e há casas que multiplicam os pontos.'],
